import {
  collides,
  step,
  makeBricks,
  createState,
  bounceOffBricks,
  BRICK_ROWS,
  BRICK_COLS,
  WIDTH,
} from './neon.js';

// --- Brick bounce (ISSUES.md #1) -------------------------------------------
// Expected behavior: the axis with the SMALLER penetration is the face that
// was hit (flip vy on top/bottom, vx on a side hit, both on a corner), the
// ball is pushed back out of the brick, the bounce applies exactly once per
// pass (seam between two bricks), and a fast ball is caught by a sweep.

test('bounceOffBricks: head-on bottom-face hit flips vy and pushes the ball out', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  const ball = { x: 136, y: 126, r: 7, vx: 120, vy: -300 }; // rising into the bottom face
  const hits = bounceOffBricks(ball, [brick], 136, 145); // swept from below, clear
  assert.deepEqual(hits, [brick]);
  assert.equal(ball.vy, 300, 'vy should flip from up to down');
  assert.equal(ball.vx, 120, 'vx must be left exactly as it was');
  assert.equal(collides(ball, brick), false, 'ball must be pushed out of the brick');
  assert.ok(ball.y - ball.r >= brick.y + brick.h, 'ball rests below the brick');
});

test('bounceOffBricks: side hit flips vx and pushes the ball out', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  const ball = { x: 95, y: 110, r: 7, vx: 300, vy: 40 }; // moving right into the left face
  const hits = bounceOffBricks(ball, [brick], 88, 110); // swept from the left, clear
  assert.deepEqual(hits, [brick]);
  assert.equal(ball.vx, -300, 'vx should flip from right to left');
  assert.equal(ball.vy, 40, 'vy must be left exactly as it was');
  assert.equal(collides(ball, brick), false, 'ball must be pushed out of the brick');
  assert.ok(ball.x + ball.r <= brick.x, 'ball rests left of the brick');
});

test('bounceOffBricks: corner hit (equal penetration) flips both axes', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  const ball = { x: 94, y: 94, r: 7, vx: 300, vy: 300 }; // diagonal into the top-left corner
  const hits = bounceOffBricks(ball, [brick], 94, 94);
  assert.deepEqual(hits, [brick]);
  assert.equal(ball.vx, -300, 'vx flipped on a corner hit');
  assert.equal(ball.vy, -300, 'vy flipped on a corner hit');
  assert.equal(collides(ball, brick), false, 'ball must be pushed out of the brick');
});

test('bounceOffBricks: seam overlap with two bricks bounces exactly once', () => {
  const a = { x: 136, y: 100, w: 72, h: 20, alive: true };
  const b = { x: 136, y: 128, w: 72, h: 20, alive: true };
  const ball = { x: 180, y: 124, r: 7, vx: 0, vy: -300 }; // spans the 8 px seam
  const hits = bounceOffBricks(ball, [a, b], 180, 124);
  assert.equal(hits.length, 2, 'both seam bricks are hit');
  assert.ok(hits.includes(a) && hits.includes(b));
  assert.equal(ball.vy, 300, 'vy flipped exactly once (a double flip would cancel out)');
  assert.equal(ball.vx, 0, 'vx untouched');
});

test('bounceOffBricks: fast ball is caught by the sweep (no tunnelling)', () => {
  const brick = { x: 100, y: 100, w: 72, h: 20, alive: true };
  // Both endpoints are clear of the brick: only the swept path crosses it.
  const ball = { x: 136, y: 80, r: 7, vx: 0, vy: -600 };
  const hits = bounceOffBricks(ball, [brick], 136, 150);
  assert.deepEqual(hits, [brick]);
  assert.ok(ball.vy > 0, 'vy should flip down after the sweep catches the brick');
  assert.equal(collides(ball, brick), false, 'ball must be pushed out of the brick');
});

test('bounceOffBricks: dead bricks are ignored', () => {
  const dead = { x: 100, y: 100, w: 72, h: 20, alive: false };
  const ball = { x: 136, y: 126, r: 7, vx: 0, vy: -300 };
  const hits = bounceOffBricks(ball, [dead], 136, 145);
  assert.equal(hits, null);
  assert.equal(ball.vy, -300, 'velocity untouched');
  assert.equal(ball.y, 126, 'position untouched');
});

