      const pen = Math.min(penetrations(ball, brick).penX, penetrations(ball, brick).penY);
      if (pen < bestPen) {
        bestPen = pen;
        best = brick;
      }
    }
    bounceBall(ball, best);
    return hits;
  }
  return null;
